// process det list with removal+append logic, none clears.
fn process_details(input: &[Detail]) -> Vec<Detail> {
    // input is from clap, which includes default "none" if no flag given.
    // Need to detect whether user provided any --det flag. Clap will give default vector with one element none if not provided.
    // Our logic for default handling: if input == [None], return empty (no details).
    // If user provides flags, input will be those values in order. e.g., --det size --det perm => [Size, Perm]
    // If user provides --det none --det dev, input = [None, Dev]
    // So we should start empty and apply each in order.
    let mut res: Vec<Detail> = Vec::new();
    // Special case: if input is exactly [None] (default), return empty.
    // But also if input contains None as first and then other, we process normally: None clears.
    for &d in input {
        match d {
            Detail::None => {
                res.clear();
            }
            Detail::All => {
                // remove all details that are in all_details from res, then append all_details
                let all = all_details();
                res.retain(|x| !all.contains(x));
                for &item in &all {
                    // ensure not already (shouldn't be after retain, but just push)
                    if !res.contains(&item) {
                        res.push(item);
                    }
                }
            }
            Detail::Std => {
                let std = std_details();
                // remove existing that are in std
                res.retain(|x| !std.contains(x));
                for &item in &std {
                    if !res.contains(&item) {
                        res.push(item);
                    }
                }
            }
            other => {
                // remove if exists
                res.retain(|&x| x != other);
                res.push(other);
            }
        }
    }
    // De-duplicate? Our retain ensures unique and move to end.
    res
}

fn process_types(input: &[TypeFilter]) -> Vec<TypeFilter> {
    // default is all if no flag provided => input == [All]
    // If user provides flags, start empty.
    // For default case, return all_types.
    // If input is exactly [All] and it came from default, we return all.
    // But if user explicitly passed --typ all, also we should return all.
    // So we need to process similarly but with initial empty and handling None clearing and All expanding.
    let mut res: Vec<TypeFilter> = Vec::new();
    for &t in input {
        match t {
            TypeFilter::None => {
                res.clear();
            }
            TypeFilter::All => {
                let all = all_types();
                res.retain(|x| !all.contains(x));
                for &item in &all {
                    if !res.contains(&item) {
                        res.push(item);
                    }
                }
            }
            other => {
                res.retain(|&x| x != other);
                res.push(other);
            }
        }
    }
    // If input was default [All], then res will be all types (since we started empty and added All)
    // If no types after processing (e.g., -t none), res empty => means no types allowed => filter everything.
    res
}

