fn get_file_type_char(ft: &fs::FileType, meta: &fs::Metadata) -> char {
    if ft.is_dir() {
        'd'
    } else if ft.is_symlink() {
        'l'
    } else if ft.is_file() {
        'f'
    } else {
        // Check for fifo, socket, block, char via FileTypeExt
        #[cfg(unix)]
        {
            use std::os::unix::fs::FileTypeExt;
            if ft.is_fifo() {
                'p'
            } else if ft.is_socket() {
                's'
            } else if ft.is_block_device() {
                'b'
            } else if ft.is_char_device() {
                'c'
            } else {
                'f'
            }
        }
        #[cfg(not(unix))]
        {
            'f'
        }
    }
}

