    if node.is_symlink {
        return "󰌹".to_string();
    }
    // Directory icon
    if node.file_type.is_dir() {
        // special names?
        let name_lower = node.name.to_lowercase();
        // For src, maybe use 
        if name_lower == "src" {
            return "".to_string();
        }
        // For .github ?
        if name_lower == ".github" {
            return "".to_string(); // observed earlier .github icon 
        }
        // For node_modules, build, dist, etc default folder icon
        return "".to_string();
    }
    // FIFO
    #[cfg(unix)]
    {
        if node.file_type.is_fifo() {
            return "󰟥".to_string();
        }
        if node.file_type.is_socket() {
            return "󰟨".to_string();
        }
        if node.file_type.is_block_device() || node.file_type.is_char_device() {
            return "".to_string();
        }
    }
    // For regular files, decide by extension and filename
    let name = node.name.clone();
    let lower = name.to_lowercase();
    let path = Path::new(&name);
    let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();

    // README.md special
    if lower == "readme.md" || lower == "readme" {
        return "".to_string();
    }
    // Dockerfile
    if lower == "dockerfile" || lower.starts_with("dockerfile.") {
        return "".to_string();
    }
    // Makefile
    if lower == "makefile" || lower == "gnumakefile" || lower == "justfile" || lower == "makefile.toml" {
        return "󰜎".to_string();
    }
    // Cargo.toml
    if lower == "cargo.toml" {
        return "".to_string();
    }
    // Cargo.lock
    if lower == "cargo.lock" {
        return "".to_string();
    }
    // package.json, etc json
    if ext == "json" || lower.ends_with("lock.yaml") || lower == "pnpm-lock.yaml" {
        // package.json, package-lock.json, etc
        return "".to_string();
