    // md files
    if ext == "md" {
        return "".to_string();
    }
    // rs files
    if ext == "rs" {
        return "".to_string();
    }
    // js files? observed no icon for js? Actually earlier for file.js had no icon? Let's see: in icons test, file.js had no icon (empty). So maybe js has no icon in our mapping? But package.json had icon.
    // sh
