fn format_perm(meta: &fs::Metadata) -> String {
    let mode = meta.mode();
    let mut s = String::new();
    // file type already handled separately, here we need rwx for user, group, other as "rwx r-x r-x" with spaces.
    // The format observed: "rwx r-x r-x" (3 groups separated by space)
    // For each of user, group, other: rwx bits.
    let bits = [
        (mode & 0o400 != 0, mode & 0o200 != 0, mode & 0o100 != 0),
        (mode & 0o040 != 0, mode & 0o020 != 0, mode & 0o010 != 0),
        (mode & 0o004 != 0, mode & 0o002 != 0, mode & 0o001 != 0),
    ];
    for (i, (r,w,x)) in bits.iter().enumerate() {
        if i>0 { s.push(' '); }
        s.push(if *r {'r'} else {'-'});
        s.push(if *w {'w'} else {'-'});
        s.push(if *x {'x'} else {'-'});
    }
    s
}

