fn apply_collapse(nodes: Vec<Node>, collapse_enabled: bool, grid_enabled: bool, details_empty: bool) -> Vec<DisplayItem> {
    if !collapse_enabled {
        return nodes.into_iter().map(|n| DisplayItem::Single(n)).collect();
    }
    // Special case: if grid true and details empty (det none), disable collapse
    if grid_enabled && details_empty {
        return nodes.into_iter().map(|n| DisplayItem::Single(n)).collect();
    }
    // Only Cargo.toml -> Cargo.lock for now
    let mut result: Vec<DisplayItem> = Vec::new();
    // We'll need to find Cargo.lock nodes
    // Build map of name to index
    let mut cargo_lock_index: Option<usize> = None;
    for (i, node) in nodes.iter().enumerate() {
        if node.name == "Cargo.lock" {
            cargo_lock_index = Some(i);
            break;
        }
    }
    let mut cargo_toml_index: Option<usize> = None;
    for (i, node) in nodes.iter().enumerate() {
        if node.name == "Cargo.toml" {
            cargo_toml_index = Some(i);
            break;
        }
    }

    if let (Some(lock_idx), Some(toml_idx)) = (cargo_lock_index, cargo_toml_index) {
        // Both exist, collapse
        // Remove lock from list, and create collapsed item at toml position
        let mut new_nodes: Vec<Node> = Vec::new();
        let lock_node = nodes[lock_idx].clone();
        for (i, node) in nodes.into_iter().enumerate() {
            if i == lock_idx {
                continue; // skip lock, will be attached
            }
            if i == toml_idx {
                // This is toml, create collapsed
                result.push(DisplayItem::Collapsed { principal: node, child: lock_node.clone() });
            } else {
                // For nodes before toml that were after lock, need to keep order.
                // Our simple approach above of iterating and building result may have order issues because we skipped lock earlier.
                // Instead, we need to build result in sorted order excluding lock, but with toml having child.
                // The earlier algorithm where we iterate sorted list and when we encounter toml, attach lock, and skip lock, naturally keeps order of remaining nodes as sorted order minus lock.
                // Our current result building is incomplete because we pushed result directly but we also need to keep other nodes.
                // Let's redo: create a new list of DisplayItems in order of sorted nodes excluding lock, but with toml replaced by collapsed.
            }
        }
        // Redo properly:
        // We have original nodes sorted list (input)
        // We need to re-create from original sorted list, but we lost it because we consumed.
        // Let's take nodes as original before removal? Actually we have nodes still? We consumed in for loop but we can reconstruct from earlier.
        // Simpler: we will handle collapse outside this function by scanning sorted list and building display items.
        // For now, return empty to indicate we need to redo logic externally.
        // We'll instead implement collapse in a separate function that takes sorted nodes and returns display items.
        return vec![]; // placeholder, will be overwritten
    }

    nodes.into_iter().map(|n| DisplayItem::Single(n)).collect()
}

fn collapse_nodes(nodes: Vec<Node>, collapse_enabled: bool, grid_enabled: bool, details_empty: bool) -> Vec<DisplayItem> {
    if !collapse_enabled {
        return nodes.into_iter().map(DisplayItem::Single).collect();
    }
    if grid_enabled && details_empty {
        return nodes.into_iter().map(DisplayItem::Single).collect();
    }
    // Only Cargo.toml collapse
    // Find if both exist
    let has_lock = nodes.iter().any(|n| n.name == "Cargo.lock");
    let has_toml = nodes.iter().any(|n| n.name == "Cargo.toml");
    if !has_lock || !has_toml {
        return nodes.into_iter().map(DisplayItem::Single).collect();
    }
    // Build result: iterate nodes in order, skip Cargo.lock, and when encountering Cargo.toml, produce collapsed
    let lock_node = nodes.iter().find(|n| n.name == "Cargo.lock").unwrap().clone();
    let mut result = Vec::new();
    for node in nodes {
        if node.name == "Cargo.lock" {
            continue;
        }
        if node.name == "Cargo.toml" {
            result.push(DisplayItem::Collapsed { principal: node, child: lock_node.clone() });
        } else {
            result.push(DisplayItem::Single(node));
        }
    }
    result
}

fn detail_header_name(d: Detail) -> &'static str {
    match d {
        Detail::Dev => "Device",
        Detail::Ino => "inode",
        Detail::Nlink => "Link#",
        Detail::Typ => "T",
        Detail::Perm => "Permissions",
        Detail::Oct => "SUGO",
        Detail::User => "User",
        Detail::Uid => "UID",
        Detail::Group => "Group",
        Detail::Gid => "GID",
        Detail::Size => "Size",
        Detail::Blocks => "Blocks",
        Detail::Btime => "Created",
        Detail::Ctime => "Changed",
        Detail::Mtime => "Modified",
        Detail::Atime => "Accessed",
        Detail::Git => "Git",
        _ => "",
    }
}

fn detail_value(node: &Node, d: Detail, unit: Unit) -> String {
    match d {
        Detail::Dev => format!("{}", node.dev),
        Detail::Ino => format!("{}", node.ino),
        Detail::Nlink => format!("{}", node.nlink),
        Detail::Typ => format!("{}", node.typ_char),
        Detail::Perm => node.perm_string.clone(),
        Detail::Oct => node.oct_string.clone(),
        Detail::User => node.user.clone(),
        Detail::Uid => format!("{}", node.uid),
        Detail::Group => node.group.clone(),
        Detail::Gid => format!("{}", node.gid),
        Detail::Size => format_size(node.size, unit, node.is_dir),
        Detail::Blocks => {
            if node.is_dir {
                "".to_string()
            } else {
                format!("{}", node.blocks)
            }
        }
        Detail::Btime => format_time(node.btime),
        Detail::Ctime => format_time(node.ctime),
        Detail::Mtime => format_time(node.mtime),
        Detail::Atime => format_time(node.atime),
        Detail::Git => node.git_status.clone(),
        _ => "".to_string(),
    }
}

