fn process_details(input: &[Detail]) -> Vec<Detail> {
    let mut res: Vec<Detail> = Vec::new();
    for &d in input {
        match d {
            Detail::None => {
                res.clear();
            }
            Detail::All => {
                let all = all_details();
                res.retain(|x| !all.contains(x));
                for &item in &all {
                    if !res.contains(&item) {
                        res.push(item);
                    }
                }
            }
            Detail::Std => {
                let std = std_details();
                res.retain(|x| !std.contains(x));
                for &item in &std {
                    if !res.contains(&item) {
                        res.push(item);
                    }
                }
            }
            other => {
                res.retain(|&x| x != other);
                res.push(other);
            }
        }
    }
    res
}

