fn compute_importance(name: &str) -> i32 {
    if name == ".git" || name == ".DS_Store" {
        return -1;
    }
    if name == "Cargo.lock" {
        return 0;
    }
    let zero_exact = [
        ".gitignore", ".gitattributes", ".gitmodules", ".dockerignore", ".npmrc", ".yarnrc",
        ".editorconfig", ".eslintrc", ".prettierrc", ".clang-format", ".clang-tidy", ".babelrc",
        ".npmignore", ".yarnclean", ".node-version", ".nvmrc", ".ruby-version", ".python-version",
        ".flake8", ".coveragerc", ".codecov.yml", ".nycrc", ".eslintignore", ".prettierignore",
        ".localized", ".DS_Store2", ".env", ".venv", ".mypy_cache", ".pytest_cache", ".tox", ".nox",
        ".vscode", ".idea", ".github", ".gitlab-ci.yml", ".travis.yml", ".tmp", ".temp", ".cache",
        ".parcel-cache", ".next", ".nuxt", ".output", ".vercel", ".turbo", ".angular", ".svelte-kit",
        ".direnv", ".coverage", ".hg", ".svn",
    ];
    if zero_exact.contains(&name) {
        return 0;
    }
    if name.starts_with(".env.") || name.starts_with(".eslintrc.") || name.starts_with(".prettierrc.") || name.starts_with(".babelrc.") || name.starts_with(".nycrc.") {
        return 0;
    }
    if name == "src" {
        return 2;
    }
    if name == "README" || name == "README.md" || name == "README.MD" || name == "README.txt" {
        return 3;
    }
    1
}

fn format_perm(mode: u32) -> String {
    let bits = [
        (mode & 0o400 != 0, mode & 0o200 != 0, mode & 0o100 != 0),
        (mode & 0o040 != 0, mode & 0o020 != 0, mode & 0o010 != 0),
        (mode & 0o004 != 0, mode & 0o002 != 0, mode & 0o001 != 0),
    ];
    let mut s = String::new();
    for (i, (r,w,x)) in bits.iter().enumerate() {
        if i>0 { s.push(' '); }
        s.push(if *r {'r'} else {'-'});
        s.push(if *w {'w'} else {'-'});
        s.push(if *x {'x'} else {'-'});
    }
    s
}

fn format_oct(mode: u32) -> String {
    format!("{:3o}", mode & 0o777)
}

fn format_time(ts: i64) -> String {
    // Use chrono local time
    let dt = chrono::DateTime::<chrono::Local>::from_timestamp(ts, 0).unwrap_or_else(|| chrono::Local.timestamp_opt(0,0).unwrap());
    dt.format("%Y-%b-%d %I:%M%P").to_string()
}

fn format_size(size: u64, unit: Unit, is_dir: bool) -> String {
    if is_dir {
        return "".to_string();
    }
    match unit {
        Unit::None => {
            format!("{} B", size)
        }
        Unit::Binary => {
            if size < 1024 {
                format!("{:.1}   B", size as f64)
            } else {
                let mut val = size as f64;
                let units = ["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"];
                let mut idx = 0;
                while val >= 1024.0 && idx < units.len()-1 {
                    val /= 1024.0;
                    idx += 1;
                }
                if idx == 0 {
                    format!("{:.1}   B", val)
                } else {
                    format!("{:.1} {}", val, units[idx])
                }
            }
        }
        Unit::Decimal => {
            if size < 1000 {
                format!("{:.1}  B", size as f64)
            } else {
                let mut val = size as f64;
                let units = ["B", "kB", "MB", "GB", "TB", "PB", "EB"];
                let mut idx = 0;
                while val >= 1000.0 && idx < units.len()-1 {
                    val /= 1000.0;
                    idx += 1;
                }
                if idx == 0 {
                    format!("{:.1}  B", val)
                } else {
                    format!("{:.1} {}", val, units[idx])
                }
            }
        }
    }
}

fn get_icon(node: &Node, icon_enabled: bool) -> String {
    if !icon_enabled {
        return "".to_string();
    }
    if node.is_symlink {
        return "󰌹".to_string();
    }
    if node.is_dir {
        let lower = node.name.to_lowercase();
        if lower == "src" {
            return "".to_string();
        }
        if lower == ".github" {
            return "".to_string();
        }
        if lower == "node_modules" {
            return "".to_string();
        }
        // default dir
        return "".to_string();
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::FileTypeExt;
        if node.file_type.is_fifo() {
            return "󰟥".to_string();
        }
        if node.file_type.is_socket() {
            return "󰟨".to_string();
        }
        if node.file_type.is_block_device() || node.file_type.is_char_device() {
            return "".to_string();
        }
    }
    let lower = node.name.to_lowercase();
    // check exact filenames
    if lower == "readme.md" || lower == "readme" {
        return "".to_string();
    }
    if lower == "dockerfile" || lower.starts_with("dockerfile.") {
        return "".to_string();
    }
    if lower == "makefile" || lower == "justfile" || lower == "gnumakefile" || lower == "makefile.toml" {
        return "󰜎".to_string();
    }
    if lower == "cargo.toml" {
        return "".to_string();
    }
    if lower == "cargo.lock" {
        return "".to_string();
    }
    // extension based
    let ext = Path::new(&node.name).extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
    match ext.as_str() {
        "rs" => "".to_string(),
        "md" => "".to_string(),
        "json" | "toml" | "yaml" | "yml" => "".to_string(),
        "sh" => "".to_string(),
        "txt" => "".to_string(),
        _ => {
            // gitignore etc
            if lower == ".gitignore" || lower.ends_with("gitignore") || lower == ".gitattributes" || lower == ".dockerignore" {
                return "󰊢".to_string();
            }
            if lower == ".env" || lower.starts_with(".env.") {
                return "".to_string();
            }
            if lower.starts_with("license") || lower.starts_with("licence") {
                return "".to_string();
            }
            "".to_string()
        }
    }
}

fn get_suffix(node: &Node, suffix_enabled: bool) -> String {
    if !suffix_enabled {
        return "".to_string();
    }
    if node.is_dir {
        "/".to_string()
    } else if node.is_symlink {
        "@".to_string()
    } else if node.file_type.is_fifo() {
        "|".to_string()
    } else if node.file_type.is_socket() {
        "=".to_string()
    } else {
        "".to_string()
    }
}

fn node_from_path(path: PathBuf, name_override: Option<String>) -> Option<Node> {
    let symlink_meta = match fs::symlink_metadata(&path) {
        Ok(m) => m,
        Err(_) => return None,
    };
    let file_type = symlink_meta.file_type();
    let is_symlink = file_type.is_symlink();
    let is_dir = file_type.is_dir();
    // For size etc, use symlink_meta for symlink, else meta
    let meta = &symlink_meta;
    let dev = meta.dev();
    let ino = meta.ino();
    let nlink = meta.nlink();
    let mode = meta.mode();
    let perm_string = format_perm(mode);
    let oct_string = format_oct(mode);
    let uid = meta.uid();
    let gid = meta.gid();
    let user = users::get_user_by_uid(uid).map(|u| u.name().to_string_lossy().into_owned()).unwrap_or_else(|| uid.to_string());
    let group = users::get_group_by_gid(gid).map(|g| g.name().to_string_lossy().into_owned()).unwrap_or_else(|| gid.to_string());
    let size = if is_symlink {
        // size is length of link target? Actually symlink_metadata size is length of target? On linux, symlink size is length of target string. That matches observed 8,5 etc. So use meta.len()
        meta.len()
    } else {
        meta.len()
    };
    let blocks = meta.blocks();
    let btime = 0; // birth time not easily available? Use ctime as fallback? We'll use mtime for all times if not available? But we have ctime, mtime, atime from metadata.
    // For btime, try to get creation time via metadata? On linux, birthtime may not be available. We'll use mtime as placeholder, but we need to format similar to original which used same time for all? In earlier tests, btime, ctime, mtime, atime were same for our test files (since just created). So we can use mtime for btime if birthtime not available.
    let mtime = meta.mtime();
    let ctime = meta.ctime();
    let atime = meta.atime();
    let btime = mtime; // fallback

    let typ_char = if is_symlink {
        'l'
    } else if file_type.is_dir() {
        'd'
    } else if file_type.is_file() {
        'f'
    } else {
        #[cfg(unix)]
        {
            if file_type.is_fifo() { 'p' }
            else if file_type.is_socket() { 's' }
            else if file_type.is_block_device() { 'b' }
            else if file_type.is_char_device() { 'c' }
            else { 'f' }
        }
        #[cfg(not(unix))]
        { 'f' }
    };

    let name = if let Some(n) = name_override {
        n
    } else {
        path.file_name().map(|os| os.to_string_lossy().into_owned()).unwrap_or_else(|| path.to_string_lossy().into_owned())
    };

    let symlink_target = if is_symlink {
        fs::read_link(&path).ok().map(|p| p.to_string_lossy().into_owned())
    } else {
        None
    };
    let symlink_target_path = if is_symlink {
        fs::read_link(&path).ok()
    } else {
        None
    };

    let importance = compute_importance(&name);

    Some(Node {
        path,
        name: name.clone(),
        display_name_raw: name,
        file_type,
        is_symlink,
        symlink_target,
        symlink_target_path,
        meta: meta.clone(),
        dev,
        ino,
        nlink,
        typ_char,
        perm_string,
        oct_string,
        user,
        uid,
        group,
        gid,
        size,
        blocks,
        btime,
        ctime,
        mtime,
        atime,
        git_status: "".to_string(),
        importance,
        is_dir,
    })
}

fn filter_nodes(nodes: Vec<Node>, type_filters: &[TypeFilter], exclude_re: &Option<Regex>, only_re: &Option<Regex>, imp_threshold: i32) -> Vec<Node> {
    let mut out = Vec::new();
    for node in nodes {
        // type filter
        if !type_matches_filter(&node.file_type, type_filters) {
            continue;
        }
        // exclude / only regex on name
        if let Some(re) = exclude_re {
            if re.is_match(&node.name) {
                continue;
            }
        }
        if let Some(re) = only_re {
            if !re.is_match(&node.name) {
                continue;
            }
        }
        // importance
        if node.importance < imp_threshold {
            continue;
        }
        out.push(node);
    }
    out
}

fn type_matches_filter(ft: &fs::FileType, filters: &[TypeFilter]) -> bool {
    if filters.is_empty() {
        return false;
    }
    let is_dir = ft.is_dir();
    let is_file = ft.is_file();
    let is_symlink = ft.is_symlink();
    #[cfg(unix)]
    {
        use std::os::unix::fs::FileTypeExt;
        let is_fifo = ft.is_fifo();
        let is_socket = ft.is_socket();
        let is_block = ft.is_block_device();
        let is_char = ft.is_char_device();
        for f in filters {
            match f {
                TypeFilter::Dir => if is_dir { return true; },
                TypeFilter::File => if is_file { return true; },
                TypeFilter::Symlink => if is_symlink { return true; },
                TypeFilter::Fifo => if is_fifo { return true; },
                TypeFilter::Socket => if is_socket { return true; },
                TypeFilter::BlockDevice => if is_block { return true; },
                TypeFilter::CharDevice => if is_char { return true; },
                TypeFilter::All => return true,
                TypeFilter::None => continue,
            }
        }
        false
    }
    #[cfg(not(unix))]
    {
        for f in filters {
            match f {
                TypeFilter::Dir => if is_dir { return true; },
                TypeFilter::File => if is_file { return true; },
                TypeFilter::Symlink => if is_symlink { return true; },
                _ => {},
            }
        }
        false
    }
}

fn sort_nodes(mut nodes: Vec<Node>, sort_fields: &[SortField]) -> Vec<Node> {
    if sort_fields.is_empty() {
        return nodes;
    }
    // For stable multi-sort, we sort by last field first, then earlier, using stable sort.
    // Or we can sort with comparator that checks fields in order.
    // We'll implement comparator that iterates sort_fields in order and returns first non-equal.
    // For reverse fields (ending with _), we reverse comparison.

    nodes.sort_by(|a,b| {
        for field in sort_fields {
            let ord = match field {
                SortField::Dev => a.dev.cmp(&b.dev),
                SortField::Ino => a.ino.cmp(&b.ino),
                SortField::Inode_ => b.ino.cmp(&a.ino), // reverse
                SortField::Nlink => a.nlink.cmp(&b.nlink),
                SortField::Nlinks_ => b.nlink.cmp(&a.nlink),
                SortField::Typ => get_typ_order(&a.file_type).cmp(&get_typ_order(&b.file_type)),
                SortField::Typ_ => get_typ_order(&b.file_type).cmp(&get_typ_order(&a.file_type)),
                SortField::Cat => get_category_order(&a.file_type).cmp(&get_category_order(&b.file_type)),
                SortField::Cat_ => get_category_order(&b.file_type).cmp(&get_category_order(&a.file_type)),
                SortField::User => a.user.cmp(&b.user),
                SortField::User_ => b.user.cmp(&a.user),
                SortField::Uid => a.uid.cmp(&b.uid),
                SortField::Uid_ => b.uid.cmp(&a.uid),
                SortField::Group => a.group.cmp(&b.group),
                SortField::Group_ => b.group.cmp(&a.group),
                SortField::Gid => a.gid.cmp(&b.gid),
                SortField::Gid_ => b.gid.cmp(&a.gid),
                SortField::Size => a.size.cmp(&b.size),
                SortField::Size_ => b.size.cmp(&a.size),
                SortField::Blocks => a.blocks.cmp(&b.blocks),
                SortField::Blocks_ => b.blocks.cmp(&a.blocks),
                SortField::Btime => a.btime.cmp(&b.btime),
                SortField::Btime_ => b.btime.cmp(&a.btime),
                SortField::Ctime => a.ctime.cmp(&b.ctime),
                SortField::Ctime_ => b.ctime.cmp(&a.ctime),
                SortField::Mtime => a.mtime.cmp(&b.mtime),
                SortField::Mtime_ => b.mtime.cmp(&a.mtime),
                SortField::Atime => a.atime.cmp(&b.atime),
                SortField::Atime_ => b.atime.cmp(&a.atime),
                SortField::Name => a.name.cmp(&b.name),
                SortField::Name_ => b.name.cmp(&a.name),
                SortField::Cname => a.name.to_lowercase().cmp(&b.name.to_lowercase()),
                SortField::Cname_ => b.name.to_lowercase().cmp(&a.name.to_lowercase()),
                SortField::Ext => {
                    let ext_a = Path::new(&a.name).extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
                    let ext_b = Path::new(&b.name).extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
                    ext_a.cmp(&ext_b)
                },
                SortField::Ext_ => {
                    let ext_a = Path::new(&a.name).extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
                    let ext_b = Path::new(&b.name).extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
                    ext_b.cmp(&ext_a)
                },
                SortField::None => std::cmp::Ordering::Equal,
                SortField::Dev => a.dev.cmp(&b.dev), // placeholder already handled? Actually dev reverse not allowed, but we have dev only forward. So dev_ would be invalid and won't be in list. So we keep.
                // For other reverse fields that are not allowed, they won't appear.
                _ => std::cmp::Ordering::Equal,
            };
            if ord != std::cmp::Ordering::Equal {
                return ord;
            }
        }
        std::cmp::Ordering::Equal
    });
    nodes
}

fn get_typ_order(ft: &fs::FileType) -> u8 {
    #[cfg(unix)]
    {
        if ft.is_dir() {
            0
        } else if ft.is_symlink() {
            1
        } else if ft.is_fifo() {
            2
        } else if ft.is_socket() {
            3
        } else if ft.is_file() {
            4
        } else {
            use std::os::unix::fs::FileTypeExt;
            if ft.is_block_device() {
                5
            } else if ft.is_char_device() {
                6
            } else {
                4
            }
        }
    }
    #[cfg(not(unix))]
    {
        if ft.is_dir() {0} else if ft.is_symlink(){1} else {4}
    }
}

fn get_category_order(ft: &fs::FileType) -> u8 {
    #[cfg(unix)]
    {
        if ft.is_dir() {
            0
        } else if ft.is_file() {
            1
        } else if ft.is_symlink() {
            2
        } else {
            use std::os::unix::fs::FileTypeExt;
            if ft.is_socket() {
                3
            } else if ft.is_fifo() {
                4
            } else if ft.is_block_device() {
                5
            } else if ft.is_char_device() {
                6
            } else {
                1
            }
        }
    }
    #[cfg(not(unix))]
    {
        if ft.is_dir() {0} else if ft.is_file(){1} else {2}
    }
}

