fn apply_collapse(nodes: Vec<Node>, collapse_enabled: bool, grid_enabled: bool, details_empty: bool) -> Vec<DisplayItem> {
    if !collapse_enabled {
        return nodes.into_iter().map(|n| DisplayItem::Single(n)).collect();
    }
    // Special case: if grid true and details empty (det none), disable collapse
    if grid_enabled && details_empty {
        return nodes.into_iter().map(|n| DisplayItem::Single(n)).collect();
    }
    // Only Cargo.toml -> Cargo.lock for now
    let mut result: Vec<DisplayItem> = Vec::new();
    // We'll need to find Cargo.lock nodes
    // Build map of name to index
    let mut cargo_lock_index: Option<usize> = None;
    for (i, node) in nodes.iter().enumerate() {
        if node.name == "Cargo.lock" {
