        TypeFilter::Socket,
        TypeFilter::BlockDevice,
        TypeFilter::CharDevice,
        TypeFilter::File,
    ]
}

fn process_details(input: &[Detail]) -> Vec<Detail> {
    let mut res: Vec<Detail> = Vec::new();
    for &d in input {
        match d {
            Detail::None => {
                res.clear();
            }
            Detail::All => {
                let all = all_details();
                res.retain(|x| !all.contains(x));
                for &item in &all {
                    if !res.contains(&item) {
                        res.push(item);
                    }
                }
            }
            Detail::Std => {
                let std = std_details();
                res.retain(|x| !std.contains(x));
                for &item in &std {
                    if !res.contains(&item) {
                        res.push(item);
                    }
                }
            }
            other => {
                res.retain(|&x| x != other);
                res.push(other);
            }
        }
    }
    res
}

fn process_types(input: &[TypeFilter]) -> Vec<TypeFilter> {
    let mut res: Vec<TypeFilter> = Vec::new();
    for &t in input {
        match t {
            TypeFilter::None => {
                res.clear();
            }
            TypeFilter::All => {
                let all = all_types();
                res.retain(|x| !all.contains(x));
                for &item in &all {
                    if !res.contains(&item) {
                        res.push(item);
                    }
                }
            }
            other => {
                res.retain(|&x| x != other);
                res.push(other);
            }
        }
    }
    res
}

fn process_sorts(input: &[SortField]) -> Vec<SortField> {
    let mut res: Vec<SortField> = Vec::new();
    for &s in input {
        match s {
            SortField::None => {
                res.clear();
            }
            other => {
                res.retain(|&x| x != other);
                res.push(other);
            }
        }
    }
    res
}

