    let mut res: Vec<String> = Vec::new();
    for d in input {
        if d == "none" {
            res.clear();
        } else if d == "all" {
            res.retain(|x| !all.contains(&x.as_str()));
            for item in &all {
                if !res.contains(&item.to_string()) {
                    res.push(item.to_string());
                }
            }
        } else if d == "std" {
            res.retain(|x| !std.contains(&x.as_str()));
            for item in &std {
                if !res.contains(&item.to_string()) {
                    res.push(item.to_string());
                }
            }
        } else {
            res.retain(|x| x != d);
            res.push(d.clone());
        }
    }
    res
}

