fn all_details() -> Vec<&'static str> {
    vec!["dev","ino","nlink","typ","perm","oct","user","uid","group","gid","size","blocks","btime","ctime","mtime","atime","git"]
}
fn std_details() -> Vec<&'static str> {
    vec!["nlink","typ","perm","user","group","size","mtime"]
}
fn all_types() -> Vec<&'static str> {
    vec!["dir","symlink","fifo","socket","block-device","char-device","file"]
}
fn all_sorts() -> Vec<&'static str> {
    vec!["dev","ino","nlink","typ","cat","user","uid","group","gid","size","blocks","btime","ctime","mtime","atime","name","cname","ext",
    "inode_","nlinks_","typ_","cat_","user_","uid_","group_","gid_","size_","blocks_","btime_","ctime_","mtime_","atime_","name_","cname_","ext_","none"]
}

fn process_details(input: &[String]) -> Vec<String> {
    let all = all_details();
    let std = std_details();
    let mut res: Vec<String> = Vec::new();
    for d in input {
        if d == "none" {
            res.clear();
        } else if d == "all" {
            res.retain(|x| !all.contains(&x.as_str()));
            for item in &all {
                if !res.contains(&item.to_string()) {
                    res.push(item.to_string());
                }
            }
        } else if d == "std" {
            res.retain(|x| !std.contains(&x.as_str()));
            for item in &std {
                if !res.contains(&item.to_string()) {
                    res.push(item.to_string());
                }
            }
        } else {
            res.retain(|x| x != d);
            res.push(d.clone());
        }
    }
    res
}

fn process_types(input: &[String]) -> Vec<String> {
    let all = all_types();
    let mut res: Vec<String> = Vec::new();
    for t in input {
        if t == "none" {
            res.clear();
        } else if t == "all" {
            res.retain(|x| !all.contains(&x.as_str()));
            for item in &all {
                if !res.contains(&item.to_string()) {
                    res.push(item.to_string());
                }
            }
        } else {
            res.retain(|x| x != t);
            res.push(t.clone());
        }
    }
    res
}

fn process_sorts(input: &[String]) -> Vec<String> {
    let mut res: Vec<String> = Vec::new();
    for s in input {
        if s == "none" {
            res.clear();
        } else {
            res.retain(|x| x != s);
            res.push(s.clone());
        }
    }
    res
}

#[derive(Debug, Clone)]
struct Node {
    path: PathBuf,
    name: String,
    file_type: fs::FileType,
    is_symlink: bool,
    symlink_target: Option<String>,
    dev: u64,
    ino: u64,
    nlink: u64,
    typ_char: char,
    perm_string: String,
    oct_string: String,
    user: String,
    uid: u32,
    group: String,
    gid: u32,
    size: u64,
    blocks: u64,
    btime: i64,
    ctime: i64,
    mtime: i64,
    atime: i64,
    importance: i32,
    is_dir: bool,
}

fn compute_importance(name: &str) -> i32 {
    if name == ".git" || name == ".DS_Store" {
        return -1;
    }
    if name == "Cargo.lock" {
        return 0;
    }
    let zero_exact = [
        ".gitignore", ".gitattributes", ".gitmodules", ".dockerignore", ".npmrc", ".yarnrc",
        ".editorconfig", ".eslintrc", ".prettierrc", ".clang-format", ".clang-tidy", ".babelrc",
        ".npmignore", ".yarnclean", ".node-version", ".nvmrc", ".ruby-version", ".python-version",
        ".flake8", ".coveragerc", ".codecov.yml", ".nycrc", ".eslintignore", ".prettierignore",
        ".localized", ".DS_Store2", ".env", ".venv", ".mypy_cache", ".pytest_cache", ".tox", ".nox",
        ".vscode", ".idea", ".github", ".gitlab-ci.yml", ".travis.yml", ".tmp", ".temp", ".cache",
        ".parcel-cache", ".next", ".nuxt", ".output", ".vercel", ".turbo", ".angular", ".svelte-kit",
        ".direnv", ".coverage", ".hg", ".svn",
    ];
    if zero_exact.contains(&name) {
        return 0;
    }
    if name.starts_with(".env.") || name.starts_with(".eslintrc.") || name.starts_with(".prettierrc.") || name.starts_with(".babelrc.") || name.starts_with(".nycrc.") {
        return 0;
    }
    if name == "src" {
        return 2;
    }
    if name == "README" || name == "README.md" || name == "README.MD" || name == "README.txt" {
        return 3;
    }
    1
}

fn format_perm(mode: u32) -> String {
    let bits = [
        (mode & 0o400 != 0, mode & 0o200 != 0, mode & 0o100 != 0),
        (mode & 0o040 != 0, mode & 0o020 != 0, mode & 0o010 != 0),
        (mode & 0o004 != 0, mode & 0o002 != 0, mode & 0o001 != 0),
    ];
    let mut s = String::new();
    for (i, (r,w,x)) in bits.iter().enumerate() {
        if i>0 { s.push(' '); }
        s.push(if *r {'r'} else {'-'});
        s.push(if *w {'w'} else {'-'});
        s.push(if *x {'x'} else {'-'});
    }
    s
}

fn format_oct(mode: u32) -> String {
    format!("{:3o}", mode & 0o777)
}

fn format_time(ts: i64) -> String {
    let dt = chrono::DateTime::<chrono::Local>::from_timestamp(ts, 0).unwrap_or_else(|| chrono::Local.timestamp_opt(0,0).unwrap());
    dt.format("%Y-%b-%d %I:%M%P").to_string()
}

fn format_size(size: u64, unit: &str, is_dir: bool) -> String {
    if is_dir {
        return "".to_string();
    }
    match unit {
        "none" => format!("{} B", size),
        "decimal" => {
            if size < 1000 {
                format!("{:.1}  B", size as f64)
            } else {
                let mut val = size as f64;
                let units = ["B", "kB", "MB", "GB", "TB", "PB", "EB"];
                let mut idx = 0;
                while val >= 1000.0 && idx < units.len()-1 {
                    val /= 1000.0;
                    idx += 1;
                }
                if idx == 0 {
                    format!("{:.1}  B", val)
                } else {
                    format!("{:.1} {}", val, units[idx])
                }
            }
        }
        _ => { // binary
            if size < 1024 {
                format!("{:.1}   B", size as f64)
            } else {
                let mut val = size as f64;
                let units = ["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"];
                let mut idx = 0;
                while val >= 1024.0 && idx < units.len()-1 {
                    val /= 1024.0;
                    idx += 1;
                }
                if idx == 0 {
                    format!("{:.1}   B", val)
                } else {
                    format!("{:.1} {}", val, units[idx])
                }
            }
        }
    }
}

fn get_user_name(uid: u32) -> String {
    unsafe {
        let pw = libc::getpwuid(uid);
        if pw.is_null() {
            return uid.to_string();
        }
        let name_ptr = (*pw).pw_name;
        if name_ptr.is_null() {
            return uid.to_string();
        }
        let c_str = std::ffi::CStr::from_ptr(name_ptr);
        c_str.to_string_lossy().into_owned()
    }
}

fn get_group_name(gid: u32) -> String {
    unsafe {
        let gr = libc::getgrgid(gid);
        if gr.is_null() {
            return gid.to_string();
        }
        let name_ptr = (*gr).gr_name;
        if name_ptr.is_null() {
            return gid.to_string();
        }
        let c_str = std::ffi::CStr::from_ptr(name_ptr);
        c_str.to_string_lossy().into_owned()
    }
}

fn get_icon(node: &Node, icon_enabled: bool) -> String {
    if !icon_enabled {
        return "".to_string();
    }
    if node.is_symlink {
        return "󰌹".to_string();
    }
    if node.is_dir {
        let lower = node.name.to_lowercase();
        if lower == "src" {
            return "".to_string();
        }
        if lower == ".github" {
            return "".to_string();
        }
        return "".to_string();
    }
    if node.file_type.is_fifo() {
        return "󰟥".to_string();
    }
    if node.file_type.is_socket() {
        return "󰟨".to_string();
    }
    if node.file_type.is_block_device() || node.file_type.is_char_device() {
        return "".to_string();
    }
    let lower = node.name.to_lowercase();
    if lower == "readme.md" || lower == "readme" {
        return "".to_string();
    }
    if lower == "dockerfile" || lower.starts_with("dockerfile.") {
        return "".to_string();
    }
    if lower == "makefile" || lower == "justfile" || lower == "gnumakefile" || lower == "makefile.toml" {
        return "󰜎".to_string();
    }
    if lower == "cargo.toml" {
        return "".to_string();
    }
    if lower == "cargo.lock" {
        return "".to_string();
    }
    let ext = Path::new(&node.name).extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
    match ext.as_str() {
        "rs" => "".to_string(),
        "md" => {
            if lower == "readme.md" {
                "".to_string()
            } else {
                "".to_string()
            }
        },
        "json" | "toml" | "yaml" | "yml" => "".to_string(),
        "sh" => "".to_string(),
        "txt" => "".to_string(),
        _ => {
            if lower == ".gitignore" || lower.ends_with("gitignore") || lower == ".gitattributes" || lower == ".dockerignore" {
                return "󰊢".to_string();
            }
            if lower == ".env" || lower.starts_with(".env.") {
                return "".to_string();
            }
            if lower.starts_with("license") || lower.starts_with("licence") {
                return "".to_string();
            }
            "".to_string()
        }
    }
}

fn get_suffix(node: &Node, suffix_enabled: bool) -> String {
    if !suffix_enabled {
        return "".to_string();
    }
    if node.is_dir {
        "/".to_string()
    } else if node.is_symlink {
        "@".to_string()
    } else if node.file_type.is_fifo() {
        "|".to_string()
    } else if node.file_type.is_socket() {
        "=".to_string()
    } else {
        "".to_string()
    }
}

fn node_from_path(path: PathBuf, name_override: Option<String>) -> Option<Node> {
    let symlink_meta = fs::symlink_metadata(&path).ok()?;
    let file_type = symlink_meta.file_type();
    let is_symlink = file_type.is_symlink();
    let is_dir = file_type.is_dir();
    let dev = symlink_meta.dev();
    let ino = symlink_meta.ino();
    let nlink = symlink_meta.nlink();
    let mode = symlink_meta.mode();
    let perm_string = format_perm(mode);
    let oct_string = format_oct(mode);
    let uid = symlink_meta.uid();
    let gid = symlink_meta.gid();
    let user = get_user_name(uid);
    let group = get_group_name(gid);
    let size = symlink_meta.len();
    let blocks = symlink_meta.blocks();
    let mtime = symlink_meta.mtime();
    let ctime = symlink_meta.ctime();
    let atime = symlink_meta.atime();
    let btime = mtime;
    let typ_char = if is_symlink {
        'l'
    } else if file_type.is_dir() {
        'd'
    } else if file_type.is_file() {
        'f'
    } else {
        if file_type.is_fifo() { 'p' }
        else if file_type.is_socket() { 's' }
        else if file_type.is_block_device() { 'b' }
        else if file_type.is_char_device() { 'c' }
        else { 'f' }
    };
    let name = if let Some(n) = name_override {
        n
    } else {
        path.file_name().map(|os| os.to_string_lossy().into_owned()).unwrap_or_else(|| path.to_string_lossy().into_owned())
    };
    let symlink_target = if is_symlink {
        fs::read_link(&path).ok().map(|p| p.to_string_lossy().into_owned())
    } else {
        None
    };
    let importance = compute_importance(&name);
    Some(Node {
        path,
        name: name.clone(),
        file_type,
        is_symlink,
        symlink_target,
        dev,
        ino,
        nlink,
        typ_char,
        perm_string,
        oct_string,
        user,
        uid,
        group,
        gid,
        size,
        blocks,
        btime,
        ctime,
        mtime,
        atime,
        importance,
        is_dir,
    })
}

fn type_matches_filter(ft: &fs::FileType, filters: &[String]) -> bool {
    if filters.is_empty() {
        return false;
    }
    let is_dir = ft.is_dir();
    let is_file = ft.is_file();
    let is_symlink = ft.is_symlink();
    let is_fifo = ft.is_fifo();
    let is_socket = ft.is_socket();
    let is_block = ft.is_block_device();
    let is_char = ft.is_char_device();
    for f in filters {
        match f.as_str() {
            "dir" => if is_dir { return true; },
            "file" => if is_file { return true; },
            "symlink" => if is_symlink { return true; },
            "fifo" => if is_fifo { return true; },
            "socket" => if is_socket { return true; },
            "block-device" => if is_block { return true; },
            "char-device" => if is_char { return true; },
            "all" => return true,
            "none" => continue,
            _ => {},
        }
    }
    false
}

fn filter_nodes(nodes: Vec<Node>, type_filters: &[String], exclude_re: &Option<Regex>, only_re: &Option<Regex>, imp_threshold: i32) -> Vec<Node> {
    let mut out = Vec::new();
    for node in nodes {
        if !type_matches_filter(&node.file_type, type_filters) {
            continue;
        }
        if let Some(re) = exclude_re {
            if re.is_match(&node.name) {
                continue;
            }
        }
        if let Some(re) = only_re {
            if !re.is_match(&node.name) {
                continue;
            }
        }
        if node.importance < imp_threshold {
            continue;
        }
        out.push(node);
    }
    out
}

fn get_typ_order(ft: &fs::FileType) -> u8 {
    if ft.is_dir() {
        0
    } else if ft.is_symlink() {
        1
    } else if ft.is_fifo() {
        2
    } else if ft.is_socket() {
        3
    } else if ft.is_file() {
        4
    } else {
        if ft.is_block_device() {
            5
        } else if ft.is_char_device() {
            6
        } else {
            4
        }
    }
}

fn get_category_order(ft: &fs::FileType) -> u8 {
    if ft.is_dir() {
        0
    } else if ft.is_file() {
        1
    } else if ft.is_symlink() {
        2
    } else {
        if ft.is_socket() {
            3
        } else if ft.is_fifo() {
            4
        } else if ft.is_block_device() {
            5
        } else if ft.is_char_device() {
            6
        } else {
            1
        }
    }
}

fn sort_nodes(mut nodes: Vec<Node>, sort_fields: &[String]) -> Vec<Node> {
    if sort_fields.is_empty() {
        return nodes;
    }
    nodes.sort_by(|a,b| {
        for field in sort_fields {
            let ord = match field.as_str() {
                "dev" => a.dev.cmp(&b.dev),
                "ino" => a.ino.cmp(&b.ino),
                "inode_" => b.ino.cmp(&a.ino),
                "nlink" => a.nlink.cmp(&b.nlink),
                "nlinks_" => b.nlink.cmp(&a.nlink),
                "typ" => get_typ_order(&a.file_type).cmp(&get_typ_order(&b.file_type)),
                "typ_" => get_typ_order(&b.file_type).cmp(&get_typ_order(&a.file_type)),
                "cat" => get_category_order(&a.file_type).cmp(&get_category_order(&b.file_type)),
                "cat_" => get_category_order(&b.file_type).cmp(&get_category_order(&a.file_type)),
                "user" => a.user.cmp(&b.user),
                "user_" => b.user.cmp(&a.user),
                "uid" => a.uid.cmp(&b.uid),
                "uid_" => b.uid.cmp(&a.uid),
                "group" => a.group.cmp(&b.group),
                "group_" => b.group.cmp(&a.group),
                "gid" => a.gid.cmp(&b.gid),
                "gid_" => b.gid.cmp(&a.gid),
                "size" => a.size.cmp(&b.size),
                "size_" => b.size.cmp(&a.size),
                "blocks" => a.blocks.cmp(&b.blocks),
                "blocks_" => b.blocks.cmp(&a.blocks),
                "btime" => a.btime.cmp(&b.btime),
                "btime_" => b.btime.cmp(&a.btime),
                "ctime" => a.ctime.cmp(&b.ctime),
                "ctime_" => b.ctime.cmp(&a.ctime),
                "mtime" => a.mtime.cmp(&b.mtime),
                "mtime_" => b.mtime.cmp(&a.mtime),
                "atime" => a.atime.cmp(&b.atime),
                "atime_" => b.atime.cmp(&a.atime),
                "name" => a.name.cmp(&b.name),
                "name_" => b.name.cmp(&a.name),
                "cname" => a.name.to_lowercase().cmp(&b.name.to_lowercase()),
                "cname_" => b.name.to_lowercase().cmp(&a.name.to_lowercase()),
                "ext" => {
                    let ext_a = Path::new(&a.name).extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
                    let ext_b = Path::new(&b.name).extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
                    ext_a.cmp(&ext_b)
                },
                "ext_" => {
                    let ext_a = Path::new(&a.name).extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
                    let ext_b = Path::new(&b.name).extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
                    ext_b.cmp(&ext_a)
                },
                "none" => std::cmp::Ordering::Equal,
                _ => std::cmp::Ordering::Equal,
            };
            if ord != std::cmp::Ordering::Equal {
                return ord;
            }
        }
        std::cmp::Ordering::Equal
    });
    nodes
}

#[derive(Debug)]
enum DisplayItem {
    Single(Node),
    Collapsed { principal: Node, child: Node },
}

fn collapse_nodes(nodes: Vec<Node>, collapse_enabled: bool, grid_enabled: bool, details_empty: bool) -> Vec<DisplayItem> {
    if !collapse_enabled {
        return nodes.into_iter().map(DisplayItem::Single).collect();
    }
    if grid_enabled && details_empty {
        return nodes.into_iter().map(DisplayItem::Single).collect();
    }
    let has_lock = nodes.iter().any(|n| n.name == "Cargo.lock");
    let has_toml = nodes.iter().any(|n| n.name == "Cargo.toml");
    if !has_lock || !has_toml {
        return nodes.into_iter().map(DisplayItem::Single).collect();
    }
    let lock_node = nodes.iter().find(|n| n.name == "Cargo.lock").unwrap().clone();
    let mut result = Vec::new();
    for node in nodes {
        if node.name == "Cargo.lock" {
            continue;
        }
        if node.name == "Cargo.toml" {
            result.push(DisplayItem::Collapsed { principal: node, child: lock_node.clone() });
        } else {
            result.push(DisplayItem::Single(node));
        }
    }
    result
}

fn detail_header_name(d: &str) -> &'static str {
    match d {
        "dev" => "Device",
        "ino" => "inode",
        "nlink" => "Link#",
        "typ" => "T",
        "perm" => "Permissions",
        "oct" => "SUGO",
        "user" => "User",
        "uid" => "UID",
        "group" => "Group",
        "gid" => "GID",
        "size" => "Size",
        "blocks" => "Blocks",
        "btime" => "Created",
        "ctime" => "Changed",
        "mtime" => "Modified",
        "atime" => "Accessed",
        "git" => "Git",
        _ => "",
    }
}

fn detail_value(node: &Node, d: &str, unit: &str) -> String {
    match d {
        "dev" => format!("{}", node.dev),
        "ino" => format!("{}", node.ino),
        "nlink" => format!("{}", node.nlink),
        "typ" => format!("{}", node.typ_char),
        "perm" => node.perm_string.clone(),
        "oct" => node.oct_string.clone(),
        "user" => node.user.clone(),
        "uid" => format!("{}", node.uid),
        "group" => node.group.clone(),
        "gid" => format!("{}", node.gid),
        "size" => format_size(node.size, unit, node.is_dir),
        "blocks" => {
            if node.is_dir {
                "".to_string()
            } else {
                format!("{}", node.blocks)
            }
        },
        "btime" => format_time(node.btime),
        "ctime" => format_time(node.ctime),
        "mtime" => format_time(node.mtime),
        "atime" => format_time(node.atime),
        "git" => "".to_string(),
        _ => "".to_string(),
    }
}

fn format_single_name(node: &Node, icon_enabled: bool, suffix_enabled: bool, sym_enabled: bool, align_enabled: bool, grid_enabled: bool, details_empty: bool) -> String {
    let icon_str = get_icon(node, icon_enabled);
    let suffix_str = get_suffix(node, suffix_enabled);
    let name_with_suffix = format!("{}{}", node.name, suffix_str);
    let is_dotfile = node.name.starts_with('.');

    let icon_part = if icon_enabled {
        if icon_str.is_empty() {
            "  ".to_string()
        } else {
            format!("{}  ", icon_str)
        }
    } else {
        "".to_string()
    };

    let align_space = if !align_enabled {
        "".to_string()
    } else {
        if is_dotfile {
            "".to_string()
        } else {
            if icon_enabled && !icon_str.is_empty() {
                "".to_string()
            } else {
                " ".to_string()
            }
        }
    };

    let mut result = format!("{}{}{}", icon_part, align_space, name_with_suffix);

    if sym_enabled && node.is_symlink {
        if !(grid_enabled && details_empty) {
            if let Some(target) = &node.symlink_target {
                result.push_str(&format!(" 󰁔 {}", target));
            }
        }
    }
    result
}

fn format_display_items(items: &[DisplayItem], details: &[String], unit: &str, header_enabled: bool, icon_enabled: bool, suffix_enabled: bool, sym_enabled: bool, align_enabled: bool, grid_enabled: bool, down_enabled: bool, is_tty: bool) -> String {
    let mut output = String::new();
    let details_empty = details.is_empty();

    if details_empty {
        if grid_enabled && is_tty {
            let mut names: Vec<String> = Vec::new();
            for item in items {
                match item {
                    DisplayItem::Single(node) => {
                        names.push(format_single_name(node, icon_enabled, suffix_enabled, sym_enabled, align_enabled, grid_enabled, details_empty));
                    }
                    DisplayItem::Collapsed { principal, child: _ } => {
                        names.push(format_single_name(principal, icon_enabled, suffix_enabled, sym_enabled, align_enabled, grid_enabled, details_empty));
                    }
                }
            }
            if names.is_empty() {
                return output;
            }
            let width = crossterm::terminal::size().map(|(w,_)| w as usize).unwrap_or(80);
            let max_len = names.iter().map(|s| s.chars().count()).max().unwrap_or(0);
            let col_width = max_len + 2;
            let cols = std::cmp::max(1, width / col_width);
            let rows = (names.len() + cols - 1) / cols;
            if down_enabled {
                for row in 0..rows {
                    let mut row_names: Vec<String> = Vec::new();
                    for col in 0..cols {
                        let idx = col * rows + row;
                        if idx < names.len() {
                            let name = &names[idx];
                            if col < cols -1 {
                                let pad = col_width.saturating_sub(name.chars().count());
                                row_names.push(format!("{}{}", name, " ".repeat(pad)));
                            } else {
                                row_names.push(name.clone());
                            }
                        }
                    }
                    output.push_str(&row_names.join(""));
                    output.push('\n');
                }
            } else {
                for chunk in names.chunks(cols) {
                    let mut row = String::new();
                    for (i, name) in chunk.iter().enumerate() {
                        if i < chunk.len()-1 {
                            let pad = col_width.saturating_sub(name.chars().count());
                            row.push_str(&format!("{}{}", name, " ".repeat(pad)));
                        } else {
                            row.push_str(name);
                        }
                    }
                    output.push_str(&row);
                    output.push('\n');
                }
            }
        } else {
            for item in items {
                match item {
                    DisplayItem::Single(node) => {
                        let line = format_single_name(node, icon_enabled, suffix_enabled, sym_enabled, align_enabled, grid_enabled, details_empty);
                        output.push_str(&line);
                        output.push('\n');
                    }
                    DisplayItem::Collapsed { principal, child } => {
                        let line1 = format_single_name(principal, icon_enabled, suffix_enabled, sym_enabled, align_enabled, grid_enabled, details_empty);
                        output.push_str(&line1);
                        output.push('\n');
                        let child_raw = format_single_name(child, icon_enabled, suffix_enabled, sym_enabled, align_enabled, grid_enabled, details_empty);
                        let trimmed = child_raw.trim_start();
                        output.push_str(&format!("   └─ {}", trimmed));
                        output.push('\n');
                    }
                }
            }
        }
    } else {
        let mut display_rows: Vec<(Vec<String>, String)> = Vec::new();
        for item in items {
            match item {
                DisplayItem::Single(node) => {
                    let mut vals = Vec::new();
                    for d in details {
                        vals.push(detail_value(node, d, unit));
                    }
                    let name = format_single_name(node, icon_enabled, suffix_enabled, sym_enabled, align_enabled, grid_enabled, details_empty);
                    display_rows.push((vals, name));
                }
                DisplayItem::Collapsed { principal, child } => {
                    let mut vals_p = Vec::new();
                    for d in details {
                        vals_p.push(detail_value(principal, d, unit));
                    }
                    let name_p = format_single_name(principal, icon_enabled, suffix_enabled, sym_enabled, align_enabled, grid_enabled, details_empty);
                    display_rows.push((vals_p, name_p));
                    let mut vals_c = Vec::new();
                    for d in details {
                        vals_c.push(detail_value(child, d, unit));
                    }
                    let child_raw = format_single_name(child, icon_enabled, suffix_enabled, sym_enabled, align_enabled, grid_enabled, details_empty);
                    let trimmed = child_raw.trim_start();
                    let name_c = format!("   └─ {}", trimmed);
                    display_rows.push((vals_c, name_c));
                }
            }
        }

        let mut col_widths: Vec<usize> = Vec::new();
        for (col_idx, _) in details.iter().enumerate() {
            let header = detail_header_name(&details[col_idx]);
            let mut max_len = header.chars().count();
            for (vals, _) in &display_rows {
                let len = vals[col_idx].chars().count();
                if len > max_len {
                    max_len = len;
                }
            }
            col_widths.push(max_len);
        }

        if header_enabled {
            let mut header_line = String::new();
            for (col_idx, d) in details.iter().enumerate() {
                let header = detail_header_name(d);
                let width = col_widths[col_idx];
                let is_right = matches!(d.as_str(), "dev"|"ino"|"nlink"|"oct"|"uid"|"gid"|"size"|"blocks");
                let formatted = if is_right {
                    format!("{:>width$}", header, width=width)
                } else {
                    format!("{:<width$}", header, width=width)
                };
                if col_idx>0 {
                    header_line.push(' ');
                }
                header_line.push_str(&formatted);
            }
            header_line.push_str(" Name");
            output.push_str(&header_line);
            output.push('\n');
        }

        for (vals, name) in display_rows {
            let mut line = String::new();
            for (col_idx, val) in vals.iter().enumerate() {
                let width = col_widths[col_idx];
                let d = details[col_idx].as_str();
                let is_right = matches!(d, "dev"|"ino"|"nlink"|"oct"|"uid"|"gid"|"size"|"blocks");
                let formatted = if is_right {
                    format!("{:>width$}", val, width=width)
                } else {
                    format!("{:<width$}", val, width=width)
                };
                if col_idx>0 {
                    line.push(' ');
                }
                line.push_str(&formatted);
            }
            if !vals.is_empty() {
                line.push(' ');
            }
            line.push_str(&name);
            output.push_str(&line);
            output.push('\n');
        }
    }
    output
}

fn list_directory(dir_path: &Path, type_filters: &[String], exclude_re: &Option<Regex>, only_re: &Option<Regex>, imp_threshold: i32, sort_fields: &[String]) -> Vec<Node> {
    let mut nodes = Vec::new();
    let read = match fs::read_dir(dir_path) {
        Ok(r) => r,
        Err(_) => return nodes,
    };
    for entry in read {
        if let Ok(entry) = entry {
            let path = entry.path();
            if let Some(node) = node_from_path(path, None) {
                nodes.push(node);
            }
        }
    }
    let filtered = filter_nodes(nodes, type_filters, exclude_re, only_re, imp_threshold);
    sort_nodes(filtered, sort_fields)
}

