fn type_matches_filter(ft: &fs::FileType, filters: &[String]) -> bool {
    if filters.is_empty() {
        return false;
    }
    let is_dir = ft.is_dir();
    let is_file = ft.is_file();
    let is_symlink = ft.is_symlink();
    let is_fifo = ft.is_fifo();
    let is_socket = ft.is_socket();
    let is_block = ft.is_block_device();
    let is_char = ft.is_char_device();
    for f in filters {
        match f.as_str() {
            "dir" => if is_dir { return true; },
            "file" => if is_file { return true; },
            "symlink" => if is_symlink { return true; },
            "fifo" => if is_fifo { return true; },
            "socket" => if is_socket { return true; },
            "block-device" => if is_block { return true; },
            "char-device" => if is_char { return true; },
            "all" => return true,
            "none" => continue,
            _ => {},
        }
    }
    false
}

fn filter_nodes(nodes: Vec<Node>, type_filters: &[String], exclude_re: &Option<Regex>, only_re: &Option<Regex>, imp_threshold: i32) -> Vec<Node> {
    let mut out = Vec::new();
    for node in nodes {
        if !type_matches_filter(&node.file_type, type_filters) {
            continue;
        }
        if let Some(re) = exclude_re {
            if re.is_match(&node.name) {
                continue;
            }
        }
        if let Some(re) = only_re {
            if !re.is_match(&node.name) {
                continue;
            }
        }
        if node.importance < imp_threshold {
            continue;
        }
        out.push(node);
    }
    out
}

fn get_typ_order(ft: &fs::FileType) -> u8 {
    if ft.is_dir() {
        0
    } else if ft.is_symlink() {
        1
    } else if ft.is_fifo() {
        2
    } else if ft.is_socket() {
        3
    } else if ft.is_file() {
        4
    } else {
        if ft.is_block_device() {
            5
        } else if ft.is_char_device() {
            6
        } else {
            4
        }
    }
}

fn get_category_order(ft: &fs::FileType) -> u8 {
    if ft.is_dir() {
        0
    } else if ft.is_file() {
        1
    } else if ft.is_symlink() {
        2
    } else {
        if ft.is_socket() {
            3
        } else if ft.is_fifo() {
            4
        } else if ft.is_block_device() {
            5
        } else if ft.is_char_device() {
            6
        } else {
            1
        }
    }
}

fn sort_nodes(mut nodes: Vec<Node>, sort_fields: &[String]) -> Vec<Node> {
    if sort_fields.is_empty() {
        return nodes;
    }
    nodes.sort_by(|a,b| {
        for field in sort_fields {
            let ord = match field.as_str() {
                "dev" => a.dev.cmp(&b.dev),
                "ino" => a.ino.cmp(&b.ino),
                "inode_" => b.ino.cmp(&a.ino),
                "nlink" => a.nlink.cmp(&b.nlink),
                "nlinks_" => b.nlink.cmp(&a.nlink),
                "typ" => get_typ_order(&a.file_type).cmp(&get_typ_order(&b.file_type)),
                "typ_" => get_typ_order(&b.file_type).cmp(&get_typ_order(&a.file_type)),
                "cat" => get_category_order(&a.file_type).cmp(&get_category_order(&b.file_type)),
                "cat_" => get_category_order(&b.file_type).cmp(&get_category_order(&a.file_type)),
                "user" => a.user.cmp(&b.user),
                "user_" => b.user.cmp(&a.user),
                "uid" => a.uid.cmp(&b.uid),
                "uid_" => b.uid.cmp(&a.uid),
                "group" => a.group.cmp(&b.group),
                "group_" => b.group.cmp(&a.group),
                "gid" => a.gid.cmp(&b.gid),
                "gid_" => b.gid.cmp(&a.gid),
                "size" => a.size.cmp(&b.size),
                "size_" => b.size.cmp(&a.size),
                "blocks" => a.blocks.cmp(&b.blocks),
                "blocks_" => b.blocks.cmp(&a.blocks),
                "btime" => a.btime.cmp(&b.btime),
                "btime_" => b.btime.cmp(&a.btime),
                "ctime" => a.ctime.cmp(&b.ctime),
                "ctime_" => b.ctime.cmp(&a.ctime),
                "mtime" => a.mtime.cmp(&b.mtime),
                "mtime_" => b.mtime.cmp(&a.mtime),
                "atime" => a.atime.cmp(&b.atime),
                "atime_" => b.atime.cmp(&a.atime),
                "name" => a.name.cmp(&b.name),
                "name_" => b.name.cmp(&a.name),
                "cname" => a.name.to_lowercase().cmp(&b.name.to_lowercase()),
                "cname_" => b.name.to_lowercase().cmp(&a.name.to_lowercase()),
                "ext" => {
                    let ext_a = Path::new(&a.name).extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
                    let ext_b = Path::new(&b.name).extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
                    ext_a.cmp(&ext_b)
                },
                "ext_" => {
                    let ext_a = Path::new(&a.name).extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
                    let ext_b = Path::new(&b.name).extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
                    ext_b.cmp(&ext_a)
                },
                "none" => std::cmp::Ordering::Equal,
                _ => std::cmp::Ordering::Equal,
            };
            if ord != std::cmp::Ordering::Equal {
                return ord;
            }
        }
        std::cmp::Ordering::Equal
    });
    nodes
}

#[derive(Debug)]
enum DisplayItem {
    Single(Node),
    Collapsed { principal: Node, child: Node },
}

fn collapse_nodes(nodes: Vec<Node>, collapse_enabled: bool, grid_enabled: bool, details_empty: bool) -> Vec<DisplayItem> {
    if !collapse_enabled {
        return nodes.into_iter().map(DisplayItem::Single).collect();
    }
    if grid_enabled && details_empty {
        return nodes.into_iter().map(DisplayItem::Single).collect();
    }
    let has_lock = nodes.iter().any(|n| n.name == "Cargo.lock");
    let has_toml = nodes.iter().any(|n| n.name == "Cargo.toml");
    if !has_lock || !has_toml {
        return nodes.into_iter().map(DisplayItem::Single).collect();
    }
    let lock_node = nodes.iter().find(|n| n.name == "Cargo.lock").unwrap().clone();
    let mut result = Vec::new();
    for node in nodes {
        if node.name == "Cargo.lock" {
            continue;
        }
        if node.name == "Cargo.toml" {
            result.push(DisplayItem::Collapsed { principal: node, child: lock_node.clone() });
        } else {
            result.push(DisplayItem::Single(node));
        }
    }
    result
}

fn detail_header_name(d: &str) -> &'static str {
    match d {
        "dev" => "Device",
        "ino" => "inode",
        "nlink" => "Link#",
        "typ" => "T",
        "perm" => "Permissions",
        "oct" => "SUGO",
        "user" => "User",
        "uid" => "UID",
        "group" => "Group",
        "gid" => "GID",
        "size" => "Size",
        "blocks" => "Blocks",
        "btime" => "Created",
        "ctime" => "Changed",
        "mtime" => "Modified",
        "atime" => "Accessed",
        "git" => "Git",
        _ => "",
    }
}

fn detail_value(node: &Node, d: &str, unit: &str) -> String {
    match d {
        "dev" => format!("{}", node.dev),
        "ino" => format!("{}", node.ino),
        "nlink" => format!("{}", node.nlink),
        "typ" => format!("{}", node.typ_char),
        "perm" => node.perm_string.clone(),
        "oct" => node.oct_string.clone(),
        "user" => node.user.clone(),
        "uid" => format!("{}", node.uid),
        "group" => node.group.clone(),
        "gid" => format!("{}", node.gid),
        "size" => format_size(node.size, unit, node.is_dir),
        "blocks" => {
            if node.is_dir {
                "".to_string()
            } else {
                format!("{}", node.blocks)
            }
        },
        "btime" => format_time(node.btime),
        "ctime" => format_time(node.ctime),
        "mtime" => format_time(node.mtime),
        "atime" => format_time(node.atime),
        "git" => "".to_string(),
        _ => "".to_string(),
    }
}

fn format_single_name(node: &Node, icon_enabled: bool, suffix_enabled: bool, sym_enabled: bool, align_enabled: bool, grid_enabled: bool, details_empty: bool) -> String {
    let icon_str = get_icon(node, icon_enabled);
    let suffix_str = get_suffix(node, suffix_enabled);
    let name_with_suffix = format!("{}{}", node.name, suffix_str);
    let is_dotfile = node.name.starts_with('.');

    let icon_part = if icon_enabled {
        if icon_str.is_empty() {
            "  ".to_string()
        } else {
            format!("{}  ", icon_str)
        }
    } else {
        "".to_string()
    };

    let align_space = if !align_enabled {
        "".to_string()
    } else {
        if is_dotfile {
            "".to_string()
        } else {
            if icon_enabled && !icon_str.is_empty() {
                "".to_string()
            } else {
                " ".to_string()
            }
        }
    };

    let mut result = format!("{}{}{}", icon_part, align_space, name_with_suffix);

    if sym_enabled && node.is_symlink {
        if !(grid_enabled && details_empty) {
            if let Some(target) = &node.symlink_target {
                result.push_str(&format!(" 󰁔 {}", target));
            }
        }
    }
    result
}

fn format_display_items(items: &[DisplayItem], details: &[String], unit: &str, header_enabled: bool, icon_enabled: bool, suffix_enabled: bool, sym_enabled: bool, align_enabled: bool, grid_enabled: bool, down_enabled: bool, is_tty: bool) -> String {
    let mut output = String::new();
    let details_empty = details.is_empty();

    if details_empty {
        if grid_enabled && is_tty {
            let mut names: Vec<String> = Vec::new();
            for item in items {
                match item {
                    DisplayItem::Single(node) => {
                        names.push(format_single_name(node, icon_enabled, suffix_enabled, sym_enabled, align_enabled, grid_enabled, details_empty));
                    }
                    DisplayItem::Collapsed { principal, child: _ } => {
                        names.push(format_single_name(principal, icon_enabled, suffix_enabled, sym_enabled, align_enabled, grid_enabled, details_empty));
                    }
                }
            }
            if names.is_empty() {
                return output;
            }
            let width = crossterm::terminal::size().map(|(w,_)| w as usize).unwrap_or(80);
            let max_len = names.iter().map(|s| s.chars().count()).max().unwrap_or(0);
            let col_width = max_len + 2;
            let cols = std::cmp::max(1, width / col_width);
            let rows = (names.len() + cols - 1) / cols;
            if down_enabled {
                for row in 0..rows {
                    let mut row_names: Vec<String> = Vec::new();
                    for col in 0..cols {
                        let idx = col * rows + row;
                        if idx < names.len() {
                            let name = &names[idx];
                            if col < cols -1 {
                                let pad = col_width.saturating_sub(name.chars().count());
                                row_names.push(format!("{}{}", name, " ".repeat(pad)));
                            } else {
                                row_names.push(name.clone());
                            }
                        }
                    }
                    output.push_str(&row_names.join(""));
                    output.push('\n');
                }
            } else {
                for chunk in names.chunks(cols) {
                    let mut row = String::new();
                    for (i, name) in chunk.iter().enumerate() {
                        if i < chunk.len()-1 {
                            let pad = col_width.saturating_sub(name.chars().count());
                            row.push_str(&format!("{}{}", name, " ".repeat(pad)));
                        } else {
                            row.push_str(name);
                        }
                    }
                    output.push_str(&row);
                    output.push('\n');
                }
            }
        } else {
            for item in items {
                match item {
                    DisplayItem::Single(node) => {
                        let line = format_single_name(node, icon_enabled, suffix_enabled, sym_enabled, align_enabled, grid_enabled, details_empty);
                        output.push_str(&line);
                        output.push('\n');
                    }
                    DisplayItem::Collapsed { principal, child } => {
                        let line1 = format_single_name(principal, icon_enabled, suffix_enabled, sym_enabled, align_enabled, grid_enabled, details_empty);
                        output.push_str(&line1);
                        output.push('\n');
                        let child_raw = format_single_name(child, icon_enabled, suffix_enabled, sym_enabled, align_enabled, grid_enabled, details_empty);
                        let trimmed = child_raw.trim_start();
                        output.push_str(&format!("   └─ {}", trimmed));
                        output.push('\n');
                    }
                }
            }
        }
    } else {
        let mut display_rows: Vec<(Vec<String>, String)> = Vec::new();
        for item in items {
            match item {
                DisplayItem::Single(node) => {
                    let mut vals = Vec::new();
                    for d in details {
                        vals.push(detail_value(node, d, unit));
                    }
                    let name = format_single_name(node, icon_enabled, suffix_enabled, sym_enabled, align_enabled, grid_enabled, details_empty);
                    display_rows.push((vals, name));
                }
                DisplayItem::Collapsed { principal, child } => {
                    let mut vals_p = Vec::new();
                    for d in details {
                        vals_p.push(detail_value(principal, d, unit));
                    }
                    let name_p = format_single_name(principal, icon_enabled, suffix_enabled, sym_enabled, align_enabled, grid_enabled, details_empty);
                    display_rows.push((vals_p, name_p));
                    let mut vals_c = Vec::new();
                    for d in details {
                        vals_c.push(detail_value(child, d, unit));
                    }
                    let child_raw = format_single_name(child, icon_enabled, suffix_enabled, sym_enabled, align_enabled, grid_enabled, details_empty);
                    let trimmed = child_raw.trim_start();
                    let name_c = format!("   └─ {}", trimmed);
                    display_rows.push((vals_c, name_c));
                }
            }
        }

        let mut col_widths: Vec<usize> = Vec::new();
        for (col_idx, _) in details.iter().enumerate() {
            let header = detail_header_name(&details[col_idx]);
            let mut max_len = header.chars().count();
            for (vals, _) in &display_rows {
                let len = vals[col_idx].chars().count();
                if len > max_len {
                    max_len = len;
                }
            }
            col_widths.push(max_len);
        }

        if header_enabled {
            let mut header_line = String::new();
            for (col_idx, d) in details.iter().enumerate() {
                let header = detail_header_name(d);
                let width = col_widths[col_idx];
                let is_right = matches!(d.as_str(), "dev"|"ino"|"nlink"|"oct"|"uid"|"gid"|"size"|"blocks");
                let formatted = if is_right {
                    format!("{:>width$}", header, width=width)
                } else {
                    format!("{:<width$}", header, width=width)
                };
                if col_idx>0 {
                    header_line.push(' ');
                }
                header_line.push_str(&formatted);
            }
            header_line.push_str(" Name");
            output.push_str(&header_line);
            output.push('\n');
        }

        for (vals, name) in display_rows {
            let mut line = String::new();
            for (col_idx, val) in vals.iter().enumerate() {
                let width = col_widths[col_idx];
                let d = details[col_idx].as_str();
                let is_right = matches!(d, "dev"|"ino"|"nlink"|"oct"|"uid"|"gid"|"size"|"blocks");
                let formatted = if is_right {
                    format!("{:>width$}", val, width=width)
                } else {
                    format!("{:<width$}", val, width=width)
                };
                if col_idx>0 {
                    line.push(' ');
                }
                line.push_str(&formatted);
            }
            if !vals.is_empty() {
                line.push(' ');
            }
            line.push_str(&name);
            output.push_str(&line);
            output.push('\n');
        }
    }
    output
}

fn list_directory(dir_path: &Path, type_filters: &[String], exclude_re: &Option<Regex>, only_re: &Option<Regex>, imp_threshold: i32, sort_fields: &[String]) -> Vec<Node> {
    let mut nodes = Vec::new();
    let read = match fs::read_dir(dir_path) {
        Ok(r) => r,
        Err(_) => return nodes,
    };
    for entry in read {
        if let Ok(entry) = entry {
            let path = entry.path();
            if let Some(node) = node_from_path(path, None) {
                nodes.push(node);
            }
        }
    }
    let filtered = filter_nodes(nodes, type_filters, exclude_re, only_re, imp_threshold);
    sort_nodes(filtered, sort_fields)
}

fn main() {
    let cmd = Command::new("pls")
        .version("0.0.1-beta.9")
        .about("pls is a prettier and powerful ls(1) for the pros.")
        .arg(Arg::new("paths").num_args(0..).default_value("."))
        .arg(Arg::new("det").short('d').long("det").value_parser(clap::builder::PossibleValuesParser::new(["dev","ino","nlink","typ","perm","oct","user","uid","group","gid","size","blocks","btime","ctime","mtime","atime","git","none","std","all"])).default_value("none").action(ArgAction::Append))
        .arg(Arg::new("header").short('H').long("header").value_parser(clap::builder::PossibleValuesParser::new(["true","false"])).default_value("true"))
        .arg(Arg::new("unit").short('u').long("unit").value_parser(clap::builder::PossibleValuesParser::new(["binary","decimal","none"])).default_value("binary"))
        .arg(Arg::new("grid").short('g').long("grid").value_parser(clap::builder::PossibleValuesParser::new(["true","false"])).default_value("false"))
        .arg(Arg::new("down").short('D').long("down").value_parser(clap::builder::PossibleValuesParser::new(["true","false"])).default_value("false"))
        .arg(Arg::new("icon").short('i').long("icon").value_parser(clap::builder::PossibleValuesParser::new(["true","false"])).default_value("true"))
        .arg(Arg::new("suffix").short('S').long("suffix").value_parser(clap::builder::PossibleValuesParser::new(["true","false"])).default_value("true"))
        .arg(Arg::new("sym").short('l').long("sym").value_parser(clap::builder::PossibleValuesParser::new(["true","false"])).default_value("true"))
        .arg(Arg::new("collapse").short('c').long("collapse").value_parser(clap::builder::PossibleValuesParser::new(["true","false"])).default_value("true"))
        .arg(Arg::new("align").short('a').long("align").value_parser(clap::builder::PossibleValuesParser::new(["true","false"])).default_value("true"))
        .arg(Arg::new("typ").short('t').long("typ").value_parser(clap::builder::PossibleValuesParser::new(["dir","symlink","fifo","socket","block-device","char-device","file","none","all"])).default_value("all").action(ArgAction::Append))
        .arg(Arg::new("imp").short('I').long("imp").default_value("0"))
        .arg(Arg::new("exclude").short('e').long("exclude"))
        .arg(Arg::new("only").short('o').long("only"))
        .arg(Arg::new("sort").short('s').long("sort").value_parser(clap::builder::PossibleValuesParser::new(["dev","ino","nlink","typ","cat","user","uid","group","gid","size","blocks","btime","ctime","mtime","atime","name","cname","ext","inode_","nlinks_","typ_","cat_","user_","uid_","group_","gid_","size_","blocks_","btime_","ctime_","mtime_","atime_","name_","cname_","ext_","none"])).default_values(["cat","cname"]).action(ArgAction::Append))
        ;

    let matches = cmd.get_matches();

    let raw_args: Vec<String> = std::env::args().collect();

    let has_det = raw_args.iter().any(|a| a == "-d" || a == "--det" || a.starts_with("--det="));
    let has_typ = raw_args.iter().any(|a| a == "-t" || a == "--typ" || a.starts_with("--typ="));
    let has_sort = raw_args.iter().any(|a| a == "-s" || a == "--sort" || a.starts_with("--sort="));

    let det_vals: Vec<String> = matches.get_many::<String>("det").unwrap().cloned().collect();
    let typ_vals: Vec<String> = matches.get_many::<String>("typ").unwrap().cloned().collect();
    let sort_vals: Vec<String> = matches.get_many::<String>("sort").unwrap().cloned().collect();

    let details = if !has_det {
        Vec::new()
    } else {
        process_details(&det_vals)
    };

    let type_filters = if !has_typ {
        all_types().into_iter().map(|s| s.to_string()).collect()
    } else {
        process_types(&typ_vals)
    };

    let sort_fields = if !has_sort {
        vec!["cat".to_string(), "cname".to_string()]
    } else {
        process_sorts(&sort_vals)
    };

    let header_str = matches.get_one::<String>("header").unwrap();
    let unit_str = matches.get_one::<String>("unit").unwrap();
    let grid_str = matches.get_one::<String>("grid").unwrap();
    let down_str = matches.get_one::<String>("down").unwrap();
    let icon_str = matches.get_one::<String>("icon").unwrap();
    let suffix_str = matches.get_one::<String>("suffix").unwrap();
    let sym_str = matches.get_one::<String>("sym").unwrap();
    let collapse_str = matches.get_one::<String>("collapse").unwrap();
    let align_str = matches.get_one::<String>("align").unwrap();
    let imp_str = matches.get_one::<String>("imp").unwrap();
    let imp: i32 = imp_str.parse().unwrap_or(0);

    let exclude_pat = matches.get_one::<String>("exclude");
    let only_pat = matches.get_one::<String>("only");

    let exclude_re = if let Some(pat) = exclude_pat {
        match Regex::new(pat) {
            Ok(re) => Some(re),
            Err(_) => {
                eprintln!("error: invalid value '{}' for '--exclude <EXCLUDE>': regex parse error:\n    {}\n    ^\nerror: repetition operator missing expression", pat, pat);
                std::process::exit(2);
            }
        }
    } else { None };

    let only_re = if let Some(pat) = only_pat {
        match Regex::new(pat) {
            Ok(re) => Some(re),
            Err(_) => {
                eprintln!("error: invalid value '{}' for '--only <ONLY>': regex parse error:\n    {}\n    ^\nerror: repetition operator missing expression", pat, pat);
                std::process::exit(2);
            }
        }
    } else { None };

    let header = header_str == "true";
    let unit = unit_str.clone();
    let grid = grid_str == "true";
    let down = down_str == "true";
    let icon = icon_str == "true";
    let suffix = suffix_str == "true";
    let sym = sym_str == "true";
    let collapse = collapse_str == "true";
    let align = align_str == "true";

    let path_strs: Vec<String> = matches.get_many::<String>("paths").unwrap().cloned().collect();
    let paths: Vec<PathBuf> = path_strs.iter().map(|s| PathBuf::from(s)).collect();

    let mut error_list: Vec<(PathBuf, String)> = Vec::new();
    let mut file_list: Vec<PathBuf> = Vec::new();
    let mut dir_list: Vec<PathBuf> = Vec::new();

    for p in &paths {
        match fs::symlink_metadata(p) {
            Ok(meta) => {
                if meta.is_dir() {
                    dir_list.push(p.clone());
                } else {
                    file_list.push(p.clone());
                }
            }
            Err(e) => {
                let msg = format!("error: {} (os error {})", e, e.raw_os_error().unwrap_or(2));
                error_list.push((p.clone(), msg));
            }
        }
    }

    let is_tty = std::io::stdout().is_terminal();

    if error_list.is_empty() && file_list.len() == 1 && dir_list.is_empty() && paths.len() == 1 {
        if let Some(node) = node_from_path(file_list[0].clone(), Some(file_list[0].to_string_lossy().into_owned())) {
            let filtered = filter_nodes(vec![node], &type_filters, &exclude_re, &only_re, imp);
            let sorted = sort_nodes(filtered, &sort_fields);
            let collapsed = collapse_nodes(sorted, false, grid, details.is_empty());
            let out = format_display_items(&collapsed, &details, &unit, header, icon, suffix, sym, align, grid, down, is_tty);
            print!("{}", out);
            return;
        }
    }

    let mut output = String::new();

    for (p, msg) in &error_list {
        output.push_str(&format!("{}:\n\t{}\n", p.display(), msg));
    }

    if !file_list.is_empty() {
        let mut nodes = Vec::new();
        for fp in &file_list {
            if let Some(node) = node_from_path(fp.clone(), Some(fp.to_string_lossy().into_owned())) {
                nodes.push(node);
            }
        }
        let filtered = filter_nodes(nodes, &type_filters, &exclude_re, &only_re, imp);
        let sorted = sort_nodes(filtered, &sort_fields);
        let collapsed = collapse_nodes(sorted, false, grid, details.is_empty());
        let out = format_display_items(&collapsed, &details, &unit, header, icon, suffix, sym, align, grid, down, is_tty);
        output.push_str(&out);
    }

    let multiple = paths.len() > 1;
    for dir_path in dir_list.iter() {
        let nodes = list_directory(dir_path, &type_filters, &exclude_re, &only_re, imp, &sort_fields);
        let collapsed = collapse_nodes(nodes, collapse, grid, details.is_empty());
        let dir_out = format_display_items(&collapsed, &details, &unit, header, icon, suffix, sym, align, grid, down, is_tty);

        if multiple || !file_list.is_empty() || !error_list.is_empty() {
            if !output.is_empty() && !output.ends_with("\n\n") {
                if output.ends_with("\n") {
                    output.push('\n');
                } else {
                    output.push_str("\n\n");
                }
            }
            output.push_str(&format!("{}:\n", dir_path.display()));
            if !dir_out.is_empty() {
                output.push_str(&dir_out);
            }
        } else {
            output.push_str(&dir_out);
        }
    }

    print!("{}", output);
}
