# For header true, column width includes header length. For header false, column width should be based only on data max length? That would make Link# column width = max data width (maybe 1? But we have 1 digit for nlink 2, etc, so width 1?). But original header false shows "2" with no leading spaces, width 1. So yes, when header false, widths are based only on data, not header.

# For header true, width includes header.

# Our current code computes col_widths based on header + data regardless of header_enabled flag. We need to make it conditional: if header_enabled, width = max(header, data), else width = max(data).

# Let's update.

cat > /tmp/fix_header_width.py <<'PY'
import pathlib
content=pathlib.Path("src/main.rs").read_text()

old = """        let mut col_widths: Vec<usize> = Vec::new();
        for (col_idx, _) in details.iter().enumerate() {
            let header = detail_header_name(&details[col_idx]);
            let mut max_len = header.chars().count();
            for (vals, _) in &display_rows {
                let len = vals[col_idx].chars().count();
                if len > max_len {
                    max_len = len;
                }
            }
            col_widths.push(max_len);
        }"""

new = """        let mut col_widths: Vec<usize> = Vec::new();
        for (col_idx, _) in details.iter().enumerate() {
            let header = detail_header_name(&details[col_idx]);
            let mut max_len = 0;
            if header_enabled {
                max_len = header.chars().count();
            }
            for (vals, _) in &display_rows {
                let len = vals[col_idx].chars().count();
                if len > max_len {
                    max_len = len;
                }
            }
            col_widths.push(max_len);
        }"""

content=content.replace(old,new,1)
pathlib.Path("src/main.rs").write_text(content)
PY
